{
  "name": "通用网络摄像头",
  "name_en": "Generic Webcam",
  "manufacturer": "",
  "description": "通用网络摄像头，用于在实验中连续采集可见光图像或视频。支持曝光、增益、分辨率和帧率设置，常用于样品观察、实验过程监控和简单视觉对位。",
  "description_en": "A generic webcam used to continuously capture visible-light images or video in laboratory workflows. It supports exposure, gain, frame size, and frame rate settings, and is commonly used for sample observation, experiment monitoring, and basic visual alignment.",
  "actions": [
    {
      "action_name": "auto-start_async",
      "description": "启动后台线程连续采集摄像头画面。",
      "description_en": "Start a background thread to continuously capture frames from the webcam."
    },
    {
      "action_name": "auto-stop",
      "description": "停止后台画面采集。",
      "description_en": "Stop background frame capture."
    },
    {
      "action_name": "auto-get_latest_frame",
      "description": "获取最新一帧图像。",
      "description_en": "Get the most recently captured frame."
    },
    {
      "action_name": "auto-set_exposure",
      "description": "设置曝光值。",
      "description_en": "Set the exposure value."
    },
    {
      "action_name": "auto-get_exposure",
      "description": "获取曝光值。",
      "description_en": "Get the exposure value."
    },
    {
      "action_name": "auto-set_gain",
      "description": "设置增益值。",
      "description_en": "Set the gain value."
    },
    {
      "action_name": "auto-get_gain",
      "description": "获取增益值。",
      "description_en": "Get the gain value."
    },
    {
      "action_name": "auto-get_frame_size",
      "description": "获取图像帧尺寸。",
      "description_en": "Get the frame size."
    },
    {
      "action_name": "auto-set_frame_size",
      "description": "设置图像帧尺寸。",
      "description_en": "Set the frame size."
    },
    {
      "action_name": "auto-get_fps",
      "description": "获取帧率。",
      "description_en": "Get the frame rate."
    },
    {
      "action_name": "auto-set_fps",
      "description": "设置帧率。",
      "description_en": "Set the frame rate."
    },
    {
      "action_name": "auto-enable_auto_exposure",
      "description": "启用或禁用自动曝光。",
      "description_en": "Enable or disable auto exposure."
    },
    {
      "action_name": "auto-discover",
      "description": "发现可用的摄像头设备。",
      "description_en": "Discover available webcam devices."
    },
    {
      "action_name": "auto-get_config_schema",
      "description": "获取摄像头配置模式定义。",
      "description_en": "Get the webcam configuration schema."
    }
  ],
  "tag_hints": [
    "webcam imaging",
    "visible-light video capture",
    "frame acquisition",
    "exposure control",
    "gain control",
    "frame size control",
    "FPS control",
    "sample monitoring"
  ]
}

